import { Inject } from '@nestjs/common';
import { DEFAULT_CONNECTION_NAME } from '../sequelize.constants.js';
import { getConnectionToken, getModelToken } from './sequelize.utils.js';
export const InjectModel = (entity, connection = DEFAULT_CONNECTION_NAME) => Inject(getModelToken(entity, connection));
export const InjectConnection = (connection) => Inject(getConnectionToken(connection));
